import com.aliyun.tea.TeaException;
import com.antgroup.antchain.openapi.dtmaas.Client;
import com.antgroup.antchain.openapi.dtmaas.models.ApiKeyModelUsageItem;
import com.antgroup.antchain.openapi.dtmaas.models.Config;
import com.antgroup.antchain.openapi.dtmaas.models.QueryApikeyUsageRequest;
import com.antgroup.antchain.openapi.dtmaas.models.QueryApikeyUsageResponse;

public class QueryApiKeyUsageExample {
    public static void main(String[] args) throws Exception {
        Config config = new Config()
                .setAccessKeyId(System.getenv("ANTDIGITAL_ACCESS_KEY_ID"))
                .setAccessKeySecret(System.getenv("ANTDIGITAL_ACCESS_KEY_SECRET"))
                .setProtocol("HTTPS")
                .setEndpoint("openapi.antdigital.com");
        Client client = new Client(config);

        QueryApikeyUsageRequest request = new QueryApikeyUsageRequest();
        request.setProductInstanceId("dtmaas-prod");
        request.setTokenId("<YOUR_TOKEN_ID>");
        request.setStartTime("2026-09-15T00:00:00+08:00");
        request.setEndTime("2026-09-16T00:00:00+08:00");
        request.setPageNum(1L);
        request.setPageSize(20L);
        request.setSortBy("callCount");
        request.setSortOrder("desc");

        try {
            QueryApikeyUsageResponse response = client.queryApikeyUsage(request);
            System.out.printf("reqMsgId=%s, resultCode=%s, resultMsg=%s%n",
                    response.getReqMsgId(), response.getResultCode(), response.getResultMsg());
            System.out.printf("total=%s, sortBy=%s, sortOrder=%s%n",
                    response.getTotal(), response.getSortBy(), response.getSortOrder());

            if (response.getUsages() == null || response.getUsages().isEmpty()) {
                System.out.println("当前页没有用量数据");
                return;
            }

            for (ApiKeyModelUsageItem usage : response.getUsages()) {
                System.out.printf(
                        "modelId=%s, callCount=%s, totalTokens=%s, "
                                + "inputTokens=%s, outputTokens=%s, cacheTokens=%s%n",
                        usage.getModelId(), usage.getCallCount(), usage.getTotalTokens(),
                        usage.getInputTokens(), usage.getOutputTokens(), usage.getCacheTokens());
            }
        } catch (TeaException exception) {
            Object reqMsgId = exception.getData() == null
                    ? null : exception.getData().get("req_msg_id");
            System.err.printf("调用失败：code=%s, message=%s, reqMsgId=%s%n",
                    exception.getCode(), exception.getMessage(), reqMsgId);
            throw exception;
        }
    }
}
